import{escapeHtml}from"./utils.js";export function renderExperienceList(e,s,a,t){return e.map(function(e){const i=e.bullets.map(function(e){return`<li>${escapeHtml(s(e))}</li>`}).join("");return`<article class="experience-card"><div class="experience-header"><div><div class="experience-meta"><span>${escapeHtml(s(e.period))}</span><span><i class="fa-solid fa-location-dot" aria-hidden="true"></i> ${escapeHtml(s(e.location))}</span></div><h3 class="experience-title">${escapeHtml(s(e.title))} · ${escapeHtml(e.company)}</h3></div><button type="button" class="experience-toggle" aria-expanded="false" data-expand-label="${escapeHtml(s(a))}" data-collapse-label="${escapeHtml(s(t))}"><span class="experience-toggle-label"></span><i class="fa-solid fa-chevron-down" aria-hidden="true"></i></button></div><div class="experience-content"><ul>${i}</ul></div></article>`}).join("")}export function renderSkillsGroups(e,s){return e.map(function(e,a){const t="group-"+(a%5+1),i=e.items.map(function(e){return`<span class="skill-chip"><i class="${escapeHtml(e.iconClass)}" aria-hidden="true"></i><span>${escapeHtml(s(e.label))}</span></span>`}).join("");return`<section class="skill-group"><h3 class="skill-group-title ${escapeHtml(t)}">${escapeHtml(s(e.label))}</h3><div class="skill-chip-list">${i}</div></section>`}).join("")}export function renderEducationList(e,s){return e.map(function(e){const a=e.extra?`<p>${escapeHtml(s(e.extra))}</p>`:"";return`<article class="info-card"><i class="${escapeHtml(e.iconClass)}" aria-hidden="true"></i><div><strong>${escapeHtml(s(e.title))}</strong><p>${escapeHtml(s(e.details))}</p>`+a+"</div></article>"}).join("")}export function renderCertificationsList(e,s){return e.map(function(e){const a=(e.skills??[]).map(function(e){return`<span class="cert-skill-tag">${escapeHtml(s(e))}</span>`}).join(""),t=e.expires?`<p class="cert-meta-line">${escapeHtml(s(e.expires))}</p>`:"",i=e.credentialId?`<p class="cert-meta-line">${escapeHtml(s(e.credentialId))}</p>`:"";return`<article class="info-card cert-card"><i class="${escapeHtml(e.iconClass)}" aria-hidden="true"></i><div><strong>${escapeHtml(s(e.title))}</strong><p class="cert-meta-line">${escapeHtml(s(e.issuer))}</p><p class="cert-meta-line">${escapeHtml(s(e.issued))}</p>`+t+i+(a?`<div class="cert-skill-row">${a}</div>`:"")+"</div></article>"}).join("")}